widget.solution:
from math import erf, exp, log, sqrt

def Phi(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_call(S, K, r, sigma, T):
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * Phi(d1) - K * exp(-r * T) * Phi(d1 - sigma * sqrt(T))

def rule_with_rate(S, K, r, sigma, T):
    """Return (rule, exact, error), error = rule - exact.
    rule = 0.4 * sigma * sqrt(T) * S + 0.5 * (S - K * exp(-r * T)).
    The rule is for the money: it is meant for K near the forward."""
    rule = 0.4 * sigma * sqrt(T) * S + 0.5 * (S - K * exp(-r * T))
    exact = bs_call(S, K, r, sigma, T)
    return rule, exact, rule - exact
